"""One-use, hash-checked transport of tested line edits; removed from the result tree."""
import hashlib
from pathlib import Path


def blob(raw):
    return hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest()

ITEMS = [{'path': 'app/server.py', 'before': '734a8a762ca46f2155b7ffeb315c6e6092a717a1', 'after': 'd8ca7c3d014d9e7a4b85a020109d41f09268660b', 'changes': [[818, 818, "                if requirement.get('path') is None:\n                    raise StudioError('Cannot resolve required model: ' + requirement['file'] + ' — ' + requirement.get('note', 'Inspect the declared location'))\n                if requirement.get('present') is not True: raise StudioError('Required model is unavailable: ' + requirement['file'])\n"], [995, 996, "            missing = {}; observations = {}\n            assets = self.library.manifest().get('assets', [])\n            from model_requirements import model_selection\n"], [999, 999, "                    for requirement in self.preset_requirements(preset, graph, assets=assets, observations=observations):\n                        if requirement['present'] is not True:\n                            label = requirement['file'] if requirement['present'] is False else 'Unresolved dependency: ' + requirement['file'] + ' — ' + requirement['note']\n                            missing.setdefault(preset.get('id'), []).append(label)\n                    # One endpoint's schema cannot speak for another backend family.\n                    if hasattr(self, 'backends') and preset.get('backend_id', 'primary') != self.backends.active: continue\n"], [1008, 1009, '                            if (field.endswith("_name") or model_selection(node.get("class_type"), field, value)) and isinstance(value, str) and isinstance(enum, list) and value not in enum:\n'], [1010, 1011, "                except (ValueError, OSError, AttributeError, TypeError) as exc:\n                    missing.setdefault(preset.get('id'), []).append('Dependency inspection unavailable: ' + str(exc)[:250])\n            missing = {key: list(dict.fromkeys(values)) for key, values in missing.items()}\n"], [1017, 1030, '        return {"id": preset_id, "requirements": self.preset_requirements(preset, graph),\n                "nodes": [{"id": key, "type": node.get("class_type")} for key, node in graph.items()], "graph": graph}\n\n    def preset_requirements(self, preset, graph, *, assets=None, observations=None):\n        from model_requirements import requirements\n'], [1032, 1040, "            model_root = Path(self.backends.profiles[preset.get('backend_id', 'primary')]['root']) / 'models'\n        return requirements(self.library, preset, graph, model_root, assets=assets, observations=observations)\n"]]}, {'path': 'app/static/app.js', 'before': '90f93d51b3c6d57c31afb1881a952c053fc31c44', 'after': 'f3c2a568025f7539d615b23a8f03a670956f89c5', 'changes': [[188, 188, 'function dependencyMarkup(r) {\n  const present=r.present===true, note=r.note || (present?\'File present\':r.present===false?\'Missing · place in the indicated folder\':\'Availability unknown · inspect this requirement\');\n  const installation=!present&&r.installable!==true ? \'<small>\'+esc(r.install_note || \'Automatic installation is unavailable; inspect the source and exact destination.\')+\'</small>\' : \'\';\n  const copy=typeof r.path===\'string\'&&r.path ? \'<button data-copy="\'+esc(r.path)+\'" title="Copy full file path">Copy path</button>\' : \'\';\n  const installable=r.present===false&&r.asset_id&&r.installable===true;\n  return \'<div class="dependency \'+(present?\'\':\'missing\')+\'"><span class="dot">\'+(present?\'●\':\'○\')+\'</span><div class="file-text"><code>\'+esc(r.file)+\'</code><small>\'+esc(note)+\'</small>\'+installation+\'</div>\'+copy+(installable?\'<button data-install="\'+esc(r.asset_id)+\'">Install</button>\':\'\')+\'</div>\';\n}\n'], [193, 194, '    $(\'#dependencies\').innerHTML = data.requirements.map(dependencyMarkup).join(\'\') || \'<p class="muted">No separate weight files in this workflow.</p>\';\n'], [261, 262, '      const pinOnly=a.installable!==true;\n'], [263, 264, '      return \'<article class="model-card"><span class="badge \'+(a.verified?\'tested\':\'\')+\'">\'+esc(state)+\'</span><h3>\'+esc(a.name)+\'</h3><p>\'+esc(a.family)+\' · \'+gib(a.bytes)+\'</p><code>\'+esc(a.file)+\'</code>\'+(a.trigger?\'<p>Trigger: <b>\'+esc(a.trigger)+\'</b></p>\':\'\')+\'<p>\'+esc(a.license)+\'</p>\'+(active?\'<progress max="\'+a.bytes+\'" value="\'+(d.bytes_done||0)+\'"></progress><p>\'+gib(d.bytes_done)+\' / \'+gib(a.bytes)+\'</p>\':\'\')+(d.status===\'failed\'?\'<p class="error">\'+esc(d.message)+\'</p>\':\'\')+\'<div class="model-actions"><a href="\'+esc(safeUrl(a.source))+\'" target="_blank" rel="noreferrer">Source ↗</a><button data-install="\'+esc(a.id)+\'" \'+(a.verified||pinOnly||busy?\'disabled\':\'\')+\' title="\'+esc(pinOnly?(a.install_note||\'Automatic installation eligibility is unknown; refresh the library.\'):\'\')+\'">\'+(a.verified?\'Installed\':pinOnly?\'Copy in by hand\':a.present?\'Verify existing file\':\'Install / use download\')+\'</button></div></article>\';\n'], [358, 359, "  try{if(copy){await navigator.clipboard.writeText(copy.dataset.copy);copy.textContent='Copied';}if(folder)await post('/api/folders/open',{id:folder.dataset.folder});if(button&&!button.disabled)await install(button.dataset.install);}catch(err){message(err.message,true);$('#downloadStatus').textContent=err.message;}\n"]]}, {'path': 'docs/OPERATIONS.md', 'before': '67394f4a9e6e220c0f33c5e2a87dd2114af16de8', 'after': 'f16af2095aac818ade7171c8106fa3211a151f03', 'changes': [[78, 78, 'The readiness panel and health response now share [exact-path model requirements](MODEL-REQUIREMENTS.md),\nincluding declared inpaint heads/patches. Unknown folders are reported rather than guessed. Install\nappears only when the existing installer explicitly supports that pin and the selected backend root;\npin-only or unsourced dependencies explain the manual/source-review path instead. File presence is\nnot a content-hash, model-compatibility or creative-acceptance claim.\n\n']]}]

for item in ITEMS:
    path=Path(item['path']); raw=path.read_bytes()
    assert blob(raw)==item['before'], 'Baseline changed: '+str(path)
    lines=raw.decode('utf-8').splitlines(keepends=True)
    for start,end,replacement in reversed(item['changes']):
        lines[start:end]=[replacement]
    result=''.join(lines).encode('utf-8')
    assert blob(result)==item['after'], 'Transport mismatch: '+str(path)
    path.write_bytes(result)
    print(path,item['after'])

expected = {
    '.github/workflows/model-readiness.yml': '60c8ee6808f2a55c354dbcd54256563f5f63bf2f',
    'app/model_requirements.py': 'c9944f52d55e1e2663129bf149495daddd50cf75',
    'docs/MODEL-REQUIREMENTS.md': 'c96ab5bc2741f5388a7650803eb9a7b7157ee1b6',
    'tests/preset_model_browser.py': '4d0da3326ed006a2fd78ed5370082b79b1cb2e0a',
    'tests/preset_model_readiness.cjs': '0a754ee88d3a6eca4afe01b2ca8d6d525eb8c00f',
    'tests/test_preset_model_frontend.py': 'ced5e75b8904523ba36fbc96b71e8f43c359fe82',
    'tests/test_preset_model_readiness.py': '4119cfa09b4225c711845a80e851043b48f74ee5',
}
for name, expected_blob in expected.items():
    observed = blob(Path(name).read_bytes())
    assert observed == expected_blob, f'Tested file differs: {name}: {observed}'
print('All ten output files match the tested source blobs.')
